      blanks: [F('التعبير الشفهي هو التعبير عن الأفكار بالكلام ____.', 'المنطوق'), F('التعبير التحري هو التعبير عن الأفكار بالـ____.', 'الكتابة'), F('الحلم المنشود هو الحلم الذي يتمناه الإنسان و____.', 'يرجوه')],
